"""Original practice questions. Numeric variants are counted separately from templates."""
import json, pathlib, math
ROOT=pathlib.Path(__file__).resolve().parent.parent
U=json.loads((ROOT/('unit3-game' if (ROOT/'unit3-game').exists() else 'unit3')/'bank.json').read_text())
EA=json.loads((ROOT/'ea-maintenance/content-bank.json' if (ROOT/'ea-maintenance').exists() else ROOT/'content-bank.json').read_text())
ub={s['id']:s for s in U['subjects']}; eb={s['id']:s for s in EA['subjects']}
qs=[]
PEO='https://peo.gov.au/understand-our-parliament/how-parliament-works/the-australian-constitution/double-majority'
TREATIES='https://humanrights.gov.au/resource-hub/by-resource-type/education/human-rights-explained/human-rights-explained-australia-and-human-rights-treaties'
RBAFX='https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html'
RBAMP='https://www.rba.gov.au/education/resources/explainers/the-transmission-of-monetary-policy.html'
def add(subject,key,title,prompt,answer,points,ut=None,et=None,stimulus='',table=None,level='medium',sources=None,kind='worked',route=None,pitfall=''):
 scopes={}
 uid=route or subject
 if ut is not None:scopes['unit3']={'route':uid,'topics':[ub[uid]['topics'][i] for i in ut]}
 if et is not None:scopes['ea']={'route':subject,'topics':[eb[subject]['topics'][i]['title'] for i in et]}
 assert scopes
 links=[{'label':'QCAA syllabus and assessment scope','url':(ub[uid] if ut is not None else eb[subject])['syllabus']}]
 links += [{'label':'Concept reference','url':s} for s in (sources or [])]
 qs.append(dict(id=f'{subject}-{key}',template=key.split('-v')[0],subject=subject,title=title,scopes=scopes,question=prompt,answer=answer,points=[{'text':t,'marks':m} for t,m in points],marks=sum(m for _,m in points),stimulus=stimulus,table=table,difficulty=level,kind=kind,pitfall=pitfall or 'Check that every part of the question has been answered and that claims use the supplied evidence.',sources=links))

# Governance and human rights are deliberately separate banks.
add('legal','referendum','A majority is not always enough','A constitutional referendum wins 54% of the national vote and a majority in only three states. Does the proposal pass? Explain.', ['No. A successful constitutional referendum requires a national majority and a majority in at least four of the six states. The national requirement is met, but the state requirement is not.'],[('Correct conclusion: does not pass',1),('National majority is met',1),('At least four states required; only three support it',1)],ut=[4],sources=[PEO],level='easy',pitfall='Do not treat the national vote alone as sufficient. Territory votes count towards the national total, not a state majority.')
add('legal','government','Representative and responsible government','Distinguish representative government from responsible government in the Australian parliamentary system.', ['Representative government means elected representatives make decisions on behalf of the people. Responsible government means the executive is accountable to parliament; a government must maintain the confidence of the lower house.'],[('Accurate explanation of representation',1),('Accurate explanation of executive accountability/confidence',1),('Clear distinction using parliamentary terminology',1)],ut=[1],sources=['https://peo.gov.au/understand-our-parliament/how-parliament-works/system-of-government/responsible-government'])
add('legal','review','Checking executive decisions','An original practice scenario: an executive agency makes decisions without giving affected people reasons. Parliament proposes mandatory reasons and independent review. Analyse one benefit and one possible limitation, then recommend a response using accountability and fairness.', ['Mandatory reasons help affected people understand and challenge a decision, improving transparency and procedural fairness. Independent review can identify errors and constrain misuse of executive power. Review can require time and resources and may delay final decisions. One defensible recommendation is reasons plus accessible independent review, with appropriate time limits and funding. This supports accountability and fairness while addressing delay.'],[('Explains a benefit linked to the scenario',1),('Explains a relevant limitation',1),('Makes a clear recommendation',1),('Justifies using accountability/fairness and an implication',1)],ut=[0,10],kind='model')
add('legal','treaty-effect','Ratification and domestic law','Does Australia’s ratification of a human rights treaty automatically make every treaty provision enforceable in Australian courts? Explain.', ['No. Ratification creates international obligations but does not by itself incorporate every provision into Australian domestic law. Existing domestic law may already implement some obligations; otherwise legislation may be needed for domestic legal effect.'],[('Correctly rejects automatic incorporation',1),('Distinguishes international obligation from domestic enforceability',1),('Explains existing law and/or implementing legislation',1)],et=[0,9],sources=[TREATIES],pitfall='Do not say ratification has no effect: international obligations and domestic enforceability are different issues.')
add('legal','declaration','Declaration and treaty','Explain one important legal difference between the UDHR and the ICCPR.', ['The UDHR is a declaration setting out human rights standards; it is not itself a treaty. The ICCPR is a treaty that creates international obligations for states that become parties. This distinction does not mean the UDHR has no legal influence or that a treaty automatically becomes domestic law.'],[('Correctly identifies the UDHR as a declaration',1),('Correctly identifies the ICCPR as a treaty with obligations for parties',1),('Explains rather than simply names the difference',1)],et=[2],sources=['https://www.ohchr.org/en/what-are-human-rights/international-bill-human-rights'])
add('legal','rights-reform','Making a justified recommendation','Use the supplied fictional proposal. Compare keeping the current process with adding free independent assistance. Recommend one using accessibility and fairness. Identify an implication.', ['Keeping the process limits additional government spending but leaves a documented access barrier. Free independent assistance could help people understand the form and present relevant information, improving accessibility and fairness. A defensible recommendation is funded assistance, with an eligibility or triage process if resources are limited. This requires funding and service capacity; monitor whether abandoned complaints decrease. Other recommendations can earn credit if justified using the criteria and evidence.'],[('Compares both alternatives with the evidence',2),('Applies accessibility and fairness',2),('Makes a justified recommendation',1),('Explains a practical implication',1)],et=[17,21,22],stimulus='Original practice data: A complaints body receives 400 attempted online applications. Of these, 120 are abandoned before submission. A survey of 50 people who abandoned an application finds that 30 did not understand the form. Option A keeps the current process. Option B funds free independent assistance. The estimated annual cost of Option B is $200,000.',kind='model',level='hard')

# Economics: explicit assumptions prevent overclaiming.
for i,(a,b,cost) in enumerate([(.70,.80,400),(.60,.75,600),(.65,.78,390)]):
 add('economics',f'fx-v{i}','What does an appreciation change?',f'The exchange rate rises from US${a:.2f} to US${b:.2f} per A$1. A US supplier keeps an item’s price at US${cost}. Calculate its Australian-dollar price before and after the change, then identify the currency movement.',[f'Before: {cost} ÷ {a} = A${cost/a:.2f}.',f'After: {cost} ÷ {b} = A${cost/b:.2f}.','The Australian dollar has appreciated: A$1 buys more US dollars. The item becomes cheaper in A$ under the stated fixed-US-price assumption.'],[('Correct initial conversion',1),('Correct later conversion',1),('Correctly identifies appreciation and its price effect',1)],ut=[2],sources=[RBAFX],level='easy',pitfall='For a US-dollar price, divide by the US dollars bought by A$1; do not multiply.')
add('economics','trade-effects','Who benefits from a depreciation?','Explain one likely benefit and one likely cost of an Australian-dollar depreciation. State an assumption or limitation.', ['With foreign-currency prices and other factors held constant, Australian exports become cheaper to overseas buyers, potentially increasing export demand and benefiting exporters. Imports become more expensive in A$, raising costs for importers and consumers. The net effect depends on demand responsiveness, contracts, imported inputs and time lags; an improved trade balance is not automatic.'],[('Explains export benefit through relative prices',1),('Explains import cost through relative prices',1),('States a relevant limitation',1)],ut=[2],sources=[RBAFX])
add('economics','trade-data','Read the trade evidence','Calculate the change in the goods trade balance. Explain why this table alone cannot establish a change in the entire current account.', ['Year 1 goods balance = 80 − 65 = a surplus of $15 billion. Year 2 = 90 − 82 = a surplus of $8 billion. The goods surplus falls by $7 billion. The current account also includes services, primary income and secondary income; these are not supplied.'],[('Calculates both goods balances',2),('Correct $7 billion decrease',1),('Explains missing current-account components',1)],ut=[3,4],table={'headers':['$ billion','Year 1','Year 2'],'rows':[['Goods exports',80,90],['Goods imports',65,82]]},sources=['https://www.abs.gov.au/statistics/economy/international-trade/balance-payments-and-international-investment-position-australia'])
add('economics','policy-chain','Trace a monetary-policy effect','Explain how a rise in interest rates can reduce inflationary pressure through household spending. Identify one reason the effect is not immediate or uniform.', ['Higher lending rates can increase repayments for borrowers and make new borrowing less attractive. Some households reduce consumption, lowering aggregate demand and demand-driven inflationary pressure. Effects vary because some loans have fixed rates, households differ in debt and savings, and decisions take time. Savers may receive more interest income.'],[('Explains a borrowing/cash-flow channel',1),('Links lower consumption to lower aggregate demand',1),('Links demand to inflationary pressure',1),('Explains one lag or uneven effect',1)],et=[8],sources=[RBAMP])
add('economics','nominal-real','Real and nominal growth','Nominal GDP rises by 8% while the GDP price index rises by 5%. Estimate real GDP growth using the exact index method.', ['Real growth factor = 1.08 ÷ 1.05 = 1.028571… . Real GDP growth ≈ 2.86%. Subtracting gives an approximation of 3%, but the exact index method adjusts multiplicatively.'],[('Uses nominal growth factor divided by price growth factor',1),('Correct percentage ≈ 2.86%',1)],et=[5],level='easy')
add('economics','policy-judgement','Evaluate an economic response','Recommend whether to prioritise the training program or a temporary consumption rebate. Use future employment as the criterion and identify a limitation.', ['One defensible recommendation is training: it targets the stated skills mismatch and could improve workers’ suitability for vacancies, supporting future employment. A rebate may lift spending and demand for labour sooner but does not directly address missing qualifications. Training takes time, must match employer needs and does not guarantee jobs. A different recommendation can earn credit if it uses the criterion, evidence and a justified causal chain.'],[('Uses the skills-mismatch evidence',1),('Compares the policies through employment effects',2),('Makes and justifies a recommendation',1),('Explains a limitation or trade-off',1)],et=[9,10,11],stimulus='Original practice scenario: Unemployment is 6.5%, but regional employers report vacancies requiring qualifications that many jobseekers do not hold. Government can fund either a two-year targeted training program or a temporary rebate on household purchases. Assume the same initial budget for either option.',kind='model',level='hard')

# Business and Accounting, with all scenario data supplied.
add('business','expansion','Choose a market-entry approach','Using control and financial exposure as criteria, compare a wholly owned outlet with licensing for this business. Recommend an approach.', ['A wholly owned outlet gives greater control over staff, service and brand presentation but places the $800,000 investment and operating risk on the business. Licensing needs less direct investment but gives less day-to-day control and requires monitoring the licensee. Given the $250,000 available budget, licensing is a defensible recommendation if brand standards and oversight are enforceable. A wholly owned outlet would require a justified financing plan.'],[('Explains control difference',1),('Explains financing/risk difference using figures',1),('Makes a feasible recommendation',1),('Justifies it using both criteria',1)],ut=[1,2],stimulus='Original practice scenario: A mature Australian business wants to enter a new overseas market. A wholly owned outlet needs $800,000 upfront. Licensing needs $100,000 for training, contracts and monitoring. The business has $250,000 available and wants consistent service quality.',kind='model')
add('business','swot','Use the evidence, not just the acronym','Identify one internal strength and one external threat. Explain one implication for expansion.', ['An experienced multilingual service team is an internal strength because it is a resource within the business. A new overseas competitor is an external threat. Expansion may use the team’s language capability, but the competitor makes differentiation and market research important; simply entering the market does not ensure sales.'],[('Correct internal strength',1),('Correct external threat',1),('Evidence-based implication',1)],ut=[4],stimulus='Original practice scenario: The firm has an experienced multilingual service team. Its existing cash reserve is small. A new overseas competitor has entered its proposed expansion market, while demand in that market is growing.',kind='model',level='easy')
add('business','change-data','Judge a transformation','Evaluate the transformation using productivity and employee retention. Recommend one refinement.', ['Output per worker rises from 20 to 26 units, a 30% increase, suggesting improved productivity. Staff turnover rises from 8% to 18%, a 10-percentage-point increase, suggesting a retention problem. The result is mixed: higher output is accompanied by greater staff loss. One refinement is staff consultation and targeted training/support, followed by monitoring both productivity and turnover. The before/after data alone do not establish that the new system caused every change.'],[('Correct productivity calculation and interpretation',2),('Correct retention interpretation',1),('Balanced judgement using both criteria',1),('Justified refinement',1)],et=[0,4,7,9],table={'headers':['Measure','Before','After'],'rows':[['Units per worker per day',20,26],['Annual staff turnover', '8%','18%']]},kind='model',level='hard')
for i,(cost,residual,life) in enumerate([(24000,4000,5),(18000,3000,6),(36000,6000,5)]):
 d=(cost-residual)/life
 add('accounting',f'depreciation-v{i}','Straight-line depreciation',f'A non-current asset costs ${cost:,}, has residual value ${residual:,} and useful life {life} years. Calculate annual straight-line depreciation and carrying amount after two complete years. Ignore GST and impairment.',[f'Annual depreciation = (cost − residual value) ÷ useful life = ({cost} − {residual}) ÷ {life} = ${d:,.0f}.',f'Accumulated depreciation after two years = ${2*d:,.0f}. Carrying amount = {cost} − {2*d:,.0f} = ${cost-2*d:,.0f}.'],[('Correct annual depreciation',1),('Correct accumulated depreciation',1),('Correct carrying amount',1)],ut=[1],level='easy')
add('accounting','disposal','Gain or loss on disposal','An asset’s historical cost is $30,000 and accumulated depreciation at disposal is $19,000. It is sold for $9,500 cash. Calculate the gain or loss. Ignore GST and selling costs.', ['Carrying amount = 30,000 − 19,000 = $11,000. Proceeds are $9,500, so there is a $1,500 loss on disposal.'],[('Correct carrying amount',1),('Correct amount and classification as loss',1)],ut=[3],level='easy')
add('accounting','accrual','A balance-day adjustment','At 30 June, a business owes $1,200 wages for work already performed. Nothing has been recorded for these wages. State the adjusting journal entry and explain the effect on profit and liabilities.', ['Debit Wages expense $1,200; credit Wages payable (or accrued wages) $1,200. Recognising the expense decreases profit by $1,200; the unpaid obligation increases current liabilities by $1,200. Cash is unchanged at this point.'],[('Correct debit',1),('Correct credit',1),('Correct profit and liability effects',1)],et=[0,1])
add('accounting','ratios','Profitability is not the same as liquidity','Calculate net profit margin and current ratio. Explain why strong sales do not by themselves prove the business can pay short-term debts.', ['Net profit margin = 36,000 ÷ 300,000 × 100 = 12%. Current ratio = 90,000 ÷ 60,000 = 1.5:1. The first ratio concerns profit relative to revenue; the second compares current assets with current liabilities. Sales may be on credit and current assets may include inventory, so timing and composition of assets matter for paying debts.'],[('Correct margin',1),('Correct current ratio',1),('Distinguishes profitability from short-term liquidity with a reason',2)],et=[5,6],stimulus='Original practice financial data: revenue $300,000; net profit $36,000; current assets $90,000; current liabilities $60,000.')

# Mathematics: several number variants per template; exact calculations checked independently.
for i,(slope,intercept,x,actual) in enumerate([(2.5,8,6,25),(3,4,8,30),(1.2,15,10,24)]):
 pred=slope*x+intercept
 add('maths_general',f'regression-v{i}','Prediction and residual',f'A fitted model is y-hat = {intercept} + {slope}x. At x = {x}, observed y = {actual}. Calculate the predicted value and residual, using residual = observed − predicted.',[f'Predicted y = {intercept} + {slope} × {x} = {pred:g}.',f'Residual = {actual} − {pred:g} = {actual-pred:g}.'],[('Correct prediction',1),('Correct signed residual',1)],ut=[1],et=[1],level='easy')
for i,(a,r,n) in enumerate([(200,1.05,4),(500,.9,3),(120,1.1,5)]):
 val=a*r**(n-1)
 add('maths_general',f'sequence-v{i}','Use the term number correctly',f'A geometric sequence has first term {a} and common ratio {r}. Find term {n}. Give your answer to two decimal places.',[f'u_n = a × r^(n−1). Therefore u_{n} = {a} × {r}^{n-1} = {val:.2f}.'],[('Correct exponent n−1',1),('Correct value and rounding',1)],ut=[3],et=[3],level='easy')
add('maths_general','seasonal','Seasonally adjusted sales','Sales in one quarter are 240 units. Its seasonal index is 1.20. Calculate seasonally adjusted sales and interpret the index.', ['Seasonally adjusted sales = 240 ÷ 1.20 = 200 units. An index of 1.20 indicates that this quarter is typically 20% above the underlying level because of its seasonal effect.'],[('Divides by the index',1),('Correct 200 units',1),('Correct interpretation of 1.20',1)],ut=[2],et=[2])
add('maths_general','timezones','Cross the date boundary','City A uses UTC+10 and City B uses UTC−5 on the date in question. It is 08:00 Monday in City A. What is the time and day in City B? Ignore daylight saving.', ['City B is 15 hours behind City A. 08:00 Monday − 15 hours = 17:00 Sunday.'],[('Correct 15-hour difference and direction',1),('Correct 17:00 Sunday',1)],ut=[4],et=[4],level='easy')
add('maths_general','association','Association and causation','A school survey finds a positive association between hours of tutoring and exam scores. Explain why this does not establish that tutoring caused the higher scores. Identify a possible confounding factor.', ['The survey is observational and does not isolate tutoring from other influences. Students with tutoring may differ in prior achievement, motivation, available time or access to resources. A specific confounder could affect both tutoring participation and scores, so the association alone does not establish causation.'],[('Recognises observational association is insufficient',1),('Identifies a plausible confounder and its role',1)],ut=[0],et=[0])
add('maths_general','networks','Critical path','Activities A (3 days) and B (5 days) start together. C (4 days) follows A. D (2 days) follows both B and C. Find the shortest project duration, the critical path and the float of B.', ['A→C finishes at day 7; B finishes at day 5. D starts at day 7 and finishes at day 9. Minimum duration is 9 days. The critical path is A–C–D. B can finish as late as day 7, so its float is 2 days.'],[('Correct 9-day duration',1),('Correct critical path',1),('Correct B float',1)],et=[10])
add('maths_general','interest','Compound growth','Invest $5,000 for three years at 4% compounded annually, with no deposits or withdrawals. Calculate the final balance to the nearest cent.', ['A = 5000 × 1.04³ = $5,624.32.'],[('Correct compound-interest expression',1),('Correct final balance',1)],et=[5],level='easy')
for i,a in enumerate([2,3,5]):
 add('maths_methods',f'exponential-v{i}','Differentiate an exponential',f'Differentiate f(x) = e^({a}x) + ln(x), for x > 0.',[f"f′(x) = {a}e^({a}x) + 1/x. The exponential term requires the chain rule."],[('Correct chain-rule exponential derivative',1),('Correct logarithmic derivative',1)],ut=[0],et=[0],level='easy')
add('maths_methods','trig','Product rule','Differentiate f(x) = x² sin(x), using radians.', ['f′(x) = 2x sin(x) + x² cos(x), by the product rule.'],[('Both product-rule contributions present',1),('Correct full derivative',1)],ut=[1],et=[1])
add('maths_methods','stationary','Classify the stationary point','For f(x) = x² − 6x + 5, find and classify the stationary point.', ['f′(x)=2x−6=0 gives x=3. f(3)=−4. Since f″(x)=2>0, (3,−4) is a local minimum.'],[('Correct stationary x',1),('Correct y-coordinate',1),('Correct classification with justification',1)],ut=[2],et=[2],level='easy')
add('maths_methods','integral','An initial condition','Given f′(x) = 6x² − 4 and f(1)=5, find f(x).', ['Integrating gives f(x)=2x³−4x+C. The condition gives 5=2−4+C, so C=7. Therefore f(x)=2x³−4x+7.'],[('Correct antiderivative including C',1),('Uses initial condition to obtain C=7',1),('Correct final function',1)],ut=[3],et=[4])
add('maths_methods','discrete','Expected value','X takes values 0, 1 and 2 with probabilities 0.2, 0.5 and 0.3. Find E(X) and P(X≥1).', ['E(X)=0×0.2+1×0.5+2×0.3=1.1. P(X≥1)=0.5+0.3=0.8.'],[('Correct expectation calculation',1),('Correct probability',1)],ut=[4],et=[5],level='easy')
add('maths_methods','normal','Standardise and interpret','X is normally distributed with mean 50 and standard deviation 8. Find the z-score for X=62. Given Φ(1.5)=0.9332, calculate P(X>62).', ['z=(62−50)/8=1.5. P(X>62)=1−0.9332=0.0668.'],[('Correct z-score',1),('Uses upper tail',1),('Correct probability',1)],et=[9])
add('maths_methods','ci','A confidence interval','In a random sample of 400, 240 people support a proposal. Using p-hat ± 1.96√[p-hat(1−p-hat)/n], calculate an approximate 95% confidence interval.', ['p-hat=240/400=0.60. Standard error=√(0.6×0.4/400)≈0.024495. Margin≈0.04801. Interval≈[0.5520,0.6480], or 55.20% to 64.80%.'],[('Correct sample proportion',1),('Correct standard error/margin',1),('Correct interval',1)],et=[11],level='hard')
add('maths_specialist','complex','De Moivre’s theorem','Write (1+i)^4 in Cartesian form.', ['1+i=√2[cos(π/4)+i sin(π/4)]. The fourth power is 4[cos(π)+i sin(π)]=−4. Expanding algebraically is also valid.'],[('Valid method',1),('Correct −4',1)],ut=[0],et=[0],level='easy')
add('maths_specialist','induction','Complete an induction argument','Prove by mathematical induction that 1+2+…+n=n(n+1)/2 for every positive integer n.', ['Base case n=1: both sides equal 1. Assume true for n=k: sum to k=k(k+1)/2. Then sum to k+1=k(k+1)/2+(k+1)=(k+1)(k+2)/2. This is the required formula for k+1, so the result holds for all positive integers by induction.'],[('Correct base case',1),('States the induction hypothesis',1),('Correct k→k+1 algebra',1),('Concludes for all positive integers',1)],ut=[1],et=[2],level='hard')
add('maths_specialist','vectors','Projection','Let a=(2,1,2) and b=(1,0,1). Find a·b and the vector projection of a onto b.', ['a·b=2+0+2=4. b·b=2. proj_b(a)=[(a·b)/(b·b)]b=2(1,0,1)=(2,0,2).'],[('Correct dot product',1),('Correct projection method',1),('Correct projected vector',1)],ut=[2],et=[3])
add('maths_specialist','vector-calculus','Velocity and acceleration','A particle has position r(t)=(t²,3t,t³). Find its velocity and acceleration at t=2.', ['v(t)=(2t,3,3t²), so v(2)=(4,3,12). a(t)=(2,0,6t), so a(2)=(2,0,12).'],[('Correct velocity function',1),('Correct v(2)',1),('Correct acceleration and a(2)',1)],ut=[3],et=[5])
add('maths_specialist','matrices','A matrix inverse','Find the inverse of A=[[2,1],[1,1]], then use it to solve 2x+y=7 and x+y=4.', ['det(A)=2×1−1×1=1. A⁻¹=[[1,−1],[−1,2]]. Multiplying A⁻¹ by (7,4) gives (3,1), so x=3 and y=1.'],[('Correct determinant/inverse',2),('Correct x and y',1)],ut=[4],et=[6])
add('maths_specialist','ode','Solve a differential equation','Solve dy/dx=2y with y(0)=3.', ['The general solution is y=Ce^(2x). The initial condition gives C=3, so y=3e^(2x).'],[('Correct exponential general solution',1),('Applies the initial condition correctly',1)],et=[9],level='easy')

# Science: all tables are original synthetic practice data, not research findings.
add('biology','quadrat','Estimate a population','Five randomly located 1 m² quadrats contain 4, 6, 5, 3 and 7 plants. Estimate the number in a uniform 200 m² habitat. Give one limitation.', ['Mean density=(4+6+5+3+7)/5=5 plants m⁻². Estimated population=5×200=1,000 plants. Five quadrats may not capture spatial variation; increase the number and use a suitable random or stratified design.'],[('Correct mean density',1),('Correct estimate with units',1),('Relevant sampling limitation',1)],ut=[0],et=[1],level='easy')
add('biology','energy','Energy transfer','Use the synthetic energy data. Calculate the percentage transfer from producers to primary consumers. Explain why transfer is not 100%.', ['Transfer=1,500/12,000×100=12.5%. Not all producer biomass is eaten or assimilated; energy is also used in respiration and dissipated as heat. Energy is not recycled through an ecosystem.'],[('Correct percentage calculation',1),('Uneaten/unassimilated material identified',1),('Respiration and heat loss explained',1)],ut=[1],et=[3],table={'headers':['Trophic level','Energy available (kJ m⁻² yr⁻¹)'],'rows':[['Producers',12000],['Primary consumers',1500],['Secondary consumers',180]]})
add('biology','inheritance','An autosomal recessive cross','Two unaffected parents are both carriers of an autosomal recessive allele a. Draw or describe the offspring genotype probabilities and the probability of an affected child. Assume simple Mendelian inheritance.', ['Aa×Aa produces AA:1/4, Aa:1/2, aa:1/4. An affected child must be aa, so the probability is 1/4 (25%) for each pregnancy. Unaffected offspring are not necessarily non-carriers.'],[('Correct parental cross',1),('Correct genotype probabilities',1),('Correct affected probability',1)],et=[11],level='easy')
add('biology','selection','Selection acts on variation','In a population, some insects already carry a heritable allele that increases survival after pesticide exposure. Explain how repeated use could change allele frequency.', ['The population has pre-existing heritable variation. Exposure selects among insects: carriers survive and reproduce at a higher rate under these conditions. They pass the allele to offspring, so its frequency can increase over generations. The pesticide does not cause individuals to develop the needed allele because they need it.'],[('Pre-existing heritable variation',1),('Differential survival and reproduction',1),('Inheritance and population allele-frequency change',1)],et=[13],sources=['https://openstax.org/books/biology-2e/pages/19-3-adaptive-evolution'])
add('chemistry','equilibrium','Calculate Kc','For H₂(g)+I₂(g) ⇌ 2HI(g), equilibrium concentrations are [H₂]=0.20 mol L⁻¹, [I₂]=0.20 mol L⁻¹ and [HI]=0.80 mol L⁻¹. Calculate Kc. If Qc=4 at the same temperature in another mixture, predict the net direction.', ['Kc=[HI]²/([H₂][I₂])=0.80²/(0.20×0.20)=16. Since Qc<Kc, the net reaction proceeds towards products until equilibrium is reached.'],[('Correct equilibrium expression',1),('Correct Kc=16',1),('Correct comparison and product direction',1)],ut=[0],et=[2])
add('chemistry','redox','A galvanic cell','Standard reduction potentials: Cu²⁺/Cu = +0.34 V; Zn²⁺/Zn = −0.76 V. Identify the anode and cathode in the spontaneous Zn–Cu cell and calculate E°cell.', ['Zinc is oxidised at the anode: Zn→Zn²⁺+2e⁻. Copper ions are reduced at the cathode: Cu²⁺+2e⁻→Cu. E°cell=E°cathode−E°anode=0.34−(−0.76)=+1.10 V.'],[('Correct anode and oxidation',1),('Correct cathode and reduction',1),('Correct potential subtraction',1)],ut=[1],et=[7,8],sources=['https://openstax.org/books/chemistry/pages/17-2-galvanic-cells'])
add('chemistry','organic','Distinguish structural isomers','Give the condensed structural formulas of the two alcohol structural isomers with molecular formula C₃H₈O. Explain why they are structural isomers.', ['Propan-1-ol: CH₃CH₂CH₂OH. Propan-2-ol: CH₃CH(OH)CH₃. They have the same molecular formula but different atom connectivity (the hydroxyl group is attached at a different carbon). An ether also has this molecular formula, but the question asks for alcohols.'],[('Correct propan-1-ol',1),('Correct propan-2-ol',1),('Correct connectivity explanation',1)],et=[9,10])
add('physics','circular','Find centripetal force','A 0.50 kg object moves in a circle of radius 2.0 m at a constant speed of 4.0 m s⁻¹. Find its centripetal acceleration and net force, including direction.', ['a=v²/r=16/2=8.0 m s⁻². F=ma=0.50×8.0=4.0 N. Both point towards the centre of the circle; velocity is tangential.'],[('Correct acceleration',1),('Correct force',1),('Correct inward direction',1)],ut=[0],et=[1],sources=['https://openstax.org/books/university-physics-volume-1/pages/6-3-centripetal-force'])
add('physics','magnetic','Magnetic force on a charge','A positive charge of 2.0×10⁻⁶ C travels at 3.0×10⁴ m s⁻¹ perpendicular to a uniform 0.20 T magnetic field. Calculate the force magnitude. What happens to the magnitude if it travels parallel to the field?', ['F=qvB sinθ=(2.0×10⁻⁶)(3.0×10⁴)(0.20)=0.012 N. For parallel motion θ=0°, so the magnetic force is zero.'],[('Correct perpendicular-force formula',1),('Correct 0.012 N',1),('Correct zero force for parallel motion',1)],ut=[1],et=[3],sources=['https://openstax.org/books/university-physics-volume-2/pages/11-3-motion-of-a-charged-particle-in-a-magnetic-field'])
add('physics','photoelectric','Photon energy and emission','Use h=6.63×10⁻³⁴ J s. Light of frequency 8.0×10¹⁴ Hz strikes a metal with work function 3.0×10⁻¹⁹ J. Find the maximum emitted electron kinetic energy. Explain the effect of doubling intensity at unchanged frequency.', ['Photon energy=hf=5.304×10⁻¹⁹ J. Kmax=hf−φ=2.304×10⁻¹⁹ J≈2.3×10⁻¹⁹ J. With frequency unchanged, Kmax is unchanged. Doubling intensity supplies more photons per second and can increase emitted electrons per second under the same suitable conditions.'],[('Correct photon energy',1),('Correct Kmax',1),('Unchanged Kmax and increased photon flux explained',2)],et=[9],sources=['https://openstax.org/books/university-physics-volume-3/pages/6-2-photoelectric-effect'])
add('earth_science','ore','Resource yield','An ore body contains 50,000 tonnes of ore with an average metal grade of 2.0% by mass. Processing recovers 80% of its contained metal. Estimate recovered metal and identify one reason grade alone cannot determine whether mining is viable.', ['Contained metal=50,000×0.02=1,000 tonnes. Recovered metal=1,000×0.80=800 tonnes. Viability also depends on factors such as extraction/processing costs, market price, access, environmental management and approvals.'],[('Correct contained metal',1),('Correct recovered metal',1),('Relevant additional viability factor',1)],ut=[0],et=[0,1])
add('earth_science','water','A renewable resource can decline','An aquifer receives 12 GL of recharge and loses 3 GL through natural discharge each year. Pumping removes 11 GL per year. Assuming these are the only flows, calculate annual storage change and propose a response.', ['Storage change=12−3−11=−2 GL per year. Under the simplified unchanged-flow model, pumping of at most 9 GL per year would avoid net storage decline. Monitoring, ecosystem needs and changing recharge must also inform a real allocation; this arithmetic is not a sustainable-yield assessment.'],[('Correct water balance',1),('Correct −2 GL decline',1),('Response linked to flows with a real-world limitation',1)],ut=[1],et=[3],sources=['https://www.ga.gov.au/scientific-topics/water/groundwater/what-is-groundwater'])
add('earth_science','climate-data','Weather and a trend','Synthetic 30-year mean temperatures for three consecutive non-overlapping periods are 18.0°C, 18.4°C and 18.9°C. Describe the change and explain why one unusually cold day would not refute it.', ['The mean increases by 0.9°C from the first to third period, with a 0.4°C increase then a 0.5°C increase. Climate concerns long-term patterns; one cold day is short-term weather variability and does not negate a long-term increase. These means alone do not identify a cause.'],[('Quantifies the 0.9°C increase',1),('Distinguishes weather from climate timescale',1),('Avoids attributing cause from these data alone',1)],et=[11])
add('marine_science','bleaching','Interpret reef observations','Using the synthetic table, compare bleaching at the two temperatures. Explain the relevant coral–algae relationship and give one limit on inference.', ['Bleaching is 60 percentage points higher at 31°C (70% versus 10%). Many shallow-water reef-building corals have symbiotic algae that supply photosynthetic products. Heat stress can disrupt this relationship and cause loss of algae/pigments, producing bleaching. Two groups without replication or full control of other variables cannot establish temperature as the sole cause. Bleached coral is not necessarily already dead.'],[('Correct percentage-point comparison',1),('Explains symbiosis and heat-stress disruption',2),('Relevant inference limitation',1)],ut=[0,1],et=[1,3],table={'headers':['Water temperature','Colonies showing bleaching'],'rows':[['28°C','10%'],['31°C','70%']]},sources=['https://www.aims.gov.au/research-topics/environmental-issues/coral-bleaching/what-coral-bleaching'])
add('marine_science','fish','A mark–recapture estimate','Researchers mark and release 80 fish. After mixing, a second random sample contains 100 fish, of which 20 are marked. Estimate population size with N≈MC/R and state two assumptions.', ['N≈80×100/20=400 fish. Assumptions include a closed population during sampling, marks retained and recognised, enough mixing, and similar capture probability for marked and unmarked fish. Any two correctly explained assumptions are acceptable.'],[('Correct substitution and estimate',2),('Two relevant assumptions',2)],et=[8])
add('psychology','memory','Compare recall results','Calculate mean recall for each condition and the mean difference. Explain why the findings alone do not establish that the technique works for all students.', ['Condition A mean=(6+8+7+9)/4=7.5 words. B mean=(10+11+9+10)/4=10 words. Difference=2.5 words in favour of B. Four results per condition are a small sample; representativeness and allocation/control of participant differences affect generalisation and causal inference.'],[('Correct two means',2),('Correct 2.5-word difference',1),('Relevant sample/design limitation',1)],ut=[2],et=[2],table={'headers':['Participant position','A: words recalled','B: words recalled'],'rows':[[1,6,10],[2,8,11],[3,7,9],[4,9,10]]})
add('psychology','conditioning','Identify classical conditioning','A neutral tone is repeatedly followed by food, which naturally makes a dog salivate. Later the tone alone makes it salivate. Identify the unconditioned stimulus and response, and the conditioned stimulus and response.', ['Unconditioned stimulus: food. Unconditioned response: salivation to food. Conditioned stimulus: the tone after pairing. Conditioned response: salivation to the tone. The same response behaviour has a different eliciting stimulus.'],[('Correct unconditioned stimulus and response',2),('Correct conditioned stimulus and response',2)],ut=[3],et=[4],sources=['https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning'],level='easy')
add('psychology','conformity','Normative influence','A student privately disagrees with a group’s answer but publicly repeats it to avoid rejection. Identify the type of social influence and distinguish it from informational influence.', ['This is normative social influence: public agreement is driven by a wish for acceptance or avoidance of rejection. Informational influence involves treating others’ responses as evidence about what is correct, particularly under uncertainty. Here the student still privately disagrees.'],[('Correct normative influence',1),('Uses private disagreement/avoidance of rejection',1),('Correct contrast with informational influence',1)],et=[6],sources=['https://openstax.org/books/psychology-2e/pages/12-4-conformity-compliance-and-obedience'])
add('agricultural_science','feed','Compare feed conversion','Group A gains 40 kg while consuming 200 kg of feed. Group B gains 50 kg while consuming 225 kg. Calculate feed conversion ratio (feed consumed/live-mass gain) for each. Which is more feed-efficient, and what else should be considered?', ['A:200/40=5.0 kg feed per kg gain. B:225/50=4.5 kg feed per kg gain. B uses less feed per unit gain. Feed cost, animal health/welfare and comparable age, conditions and feed composition should also be considered; FCR alone does not establish overall profitability.'],[('Correct two ratios',2),('Correct interpretation: B',1),('Relevant additional consideration',1)],ut=[0],et=[0])
add('agricultural_science','plants','Compare trial yields','Use the original synthetic trial results. Calculate the percentage increase from control to treatment. State a design improvement and explain why it matters.', ['Increase=(6.0−5.0)/5.0×100=20%. Randomised replicated plots would help separate treatment effects from location or chance variation; control other relevant inputs. A single plot per condition gives weak evidence for a general recommendation.'],[('Correct baseline and calculation',2),('Suitable design improvement',1),('Explains its value',1)],ut=[1],et=[3],table={'headers':['Treatment','Yield (t ha⁻¹)'],'rows':[['Control',5.0],['Treatment',6.0]]})
add('agricultural_science','enterprise','A gross margin','A crop enterprise earns $72,000 revenue and has variable costs of $45,000. Calculate gross margin. Explain why this is not necessarily net profit.', ['Gross margin=$72,000−$45,000=$27,000. It excludes fixed/overhead costs, so those and other relevant costs must be considered to determine net profit.'],[('Correct gross margin',1),('Identifies excluded fixed/overhead costs',1),('Links exclusion to net-profit distinction',1)],ut=[2],et=[8],level='easy')

# Applied subjects: different Unit 3 / EA content is intentionally kept separate.
add('engineering','beam','A simply supported beam','A 6.0 m horizontal beam is simply supported at each end. A 12 kN downward point load acts 2.0 m from the left support. Ignore beam weight. Calculate the vertical reactions.', ['Taking moments about the left support: Rright×6=12×2, so Rright=4 kN upward. Vertical equilibrium gives Rleft+4=12, so Rleft=8 kN upward.'],[('Correct moment balance',1),('Correct right reaction',1),('Correct left reaction with direction',1)],ut=[1])
add('engineering','stress','Axial stress','An axial tensile force of 20 kN acts on a member with cross-sectional area 100 mm². Calculate tensile stress in MPa. A specified allowable stress is 150 MPa. Does this meet that criterion?', ['Stress=F/A=20,000/100=200 N mm⁻²=200 MPa. It exceeds 150 MPa, so it does not meet this allowable-stress criterion. This calculation alone is not a complete structural design check.'],[('Correct force/area conversion',1),('Correct 200 MPa',1),('Correct comparison and conclusion',1)],ut=[2,3])
add('engineering','power','Efficiency and power','A motor supplies 800 W to a mechanism whose useful output is 600 W. Calculate efficiency and wasted power. If useful output must be 900 W at the same efficiency, what input is needed?', ['Efficiency=600/800=0.75=75%. Wasted power=200 W. Required input=900/0.75=1,200 W.'],[('Correct efficiency',1),('Correct loss',1),('Correct required input',1)],et=[3])
add('engineering','gears','Gear ratio','A 20-tooth driver rotates at 1,200 rpm and meshes directly with a 60-tooth driven gear. Calculate driven speed and describe direction. Ignore losses.', ['Driven speed=1,200×20/60=400 rpm. Directly meshing external gears turn in opposite directions. The ideal output torque is three times the input torque.'],[('Correct ratio/method',1),('Correct 400 rpm',1),('Correct opposite direction',1)],et=[2])
add('aerospace_sys','turnaround','Find the operational bottleneck','After an aircraft arrives, refuelling takes 18 minutes and cabin servicing takes 25 minutes; both start together. Boarding takes 15 minutes and starts only when both finish. Calculate the earliest departure-ready time after arrival. Which improvement saves more time: reducing refuelling by 5 minutes or cabin servicing by 5 minutes?', ['Parallel tasks finish when the slower one finishes: 25 minutes. Add boarding:40 minutes. Refuelling reduction leaves 40 minutes unchanged. Cabin servicing reduction makes the parallel stage max(18,20)=20 minutes, giving 35 minutes total. Reducing cabin servicing saves 5 minutes under these assumptions.'],[('Correct baseline time',1),('Correct refuelling result',1),('Correct cabin result and recommendation',2)],ut=[3,4])
add('aerospace_sys','safety','Respond to a recurring incident','A fictional airport log records 12 vehicle incursions in a month; 9 involve unclear route markings at night. Recommend one preventive change and an evaluation measure. Explain a limitation of the evidence.', ['Improve route markings and lighting at the identified location, with appropriate staff briefing. Compare incursion rates per vehicle movement before and after implementation, especially at night. Counts alone do not control for traffic volume or other conditions; the log suggests a focus but does not prove markings caused every incident. Other justified prevention measures can earn credit.'],[('Specific response linked to evidence',1),('Suitable rate-based evaluation',1),('Evidence limitation explained',1)],ut=[1,2],kind='model')
add('aerospace_sys','fuel','A planning calculation','For a classroom calculation only: a flight takes 2.0 hours at 36 L h⁻¹. Add a separately specified 18 L reserve and 6 L taxi allowance. Calculate total fuel and compare with 100 L available. Do not infer regulatory fuel minima.', ['Trip fuel=2×36=72 L. Total under the supplied planning assumptions=72+18+6=96 L. 100 L exceeds that total by 4 L. Actual flight planning requires current operational and regulatory requirements; the supplied reserve is an exercise value.'],[('Correct trip fuel',1),('Correct total',1),('Correct 4 L comparison',1)],et=[5])
add('aerospace_sys','navigation','Time and ground speed','An aircraft covers a 180 nautical mile leg at a ground speed of 120 knots. Calculate travel time. If ground speed falls to 100 knots, how much longer does it take?', ['At 120 knots:180/120=1.5 hours=90 minutes. At 100 knots:1.8 hours=108 minutes. Difference=18 minutes. Use ground speed for ground distance, rather than substituting airspeed without wind correction.'],[('Correct first time',1),('Correct second time',1),('Correct difference',1)],et=[4],level='easy')
add('food','starch','Interpret a thickening trial','Use the synthetic results. Identify the trend and recommend a tested concentration if the success criterion is a spread diameter of at most 60 mm. Explain one limitation.', ['Spread diameter decreases as starch concentration increases, consistent with a thicker paste under the test conditions. Both 6% and 8% meet the ≤60 mm criterion. A defensible choice is 6% if minimising starch/cost is an additional aim. Repeats, consistent heating and sensory testing are needed; the table alone does not establish acceptability.'],[('Correct trend using evidence',1),('Identifies both qualifying concentrations',1),('Justifies a choice and limitation',2)],ut=[0,4,5],table={'headers':['Starch concentration','Spread diameter'],'rows':[['4%','80 mm'],['6%','55 mm'],['8%','40 mm']]},kind='model')
add('food','fat','Protect a fat-rich product','A fat-rich snack develops an undesirable rancid smell faster in warm, transparent packaging than in cool, opaque packaging. Explain a plausible mechanism and propose a controlled test of packaging opacity.', ['Oxidative rancidity is a plausible mechanism: light, oxygen and temperature can influence lipid oxidation. To test opacity, compare otherwise identical opaque and transparent packs at the same temperature, oxygen exposure and storage time, using replicates and a suitable rancidity measure. The initial comparison changes both light and temperature, so it cannot isolate opacity.'],[('Plausible lipid-oxidation explanation',1),('Controls temperature and other relevant variables',1),('Replicates/measurement specified',1),('Recognises original confounding',1)],ut=[2,3],kind='model')
add('food','allergy','Evaluate a consumer formulation','A school specifies a milk-free snack for consumers with milk allergy. The proposed recipe replaces milk with lactose-free cow’s milk. Does this satisfy the criterion? Explain and suggest a better next step.', ['No. Lactose-free cow’s milk can still contain milk proteins that trigger milk allergy. Lactose intolerance and milk allergy are different. Select ingredients that meet the milk-free specification, check allergen declarations and manage cross-contact; verify the complete formulation against the consumer brief.'],[('Correct rejection',1),('Explains milk protein versus lactose distinction',1),('Suitable ingredient/allergen-control next step',1)],et=[4,6],sources=['https://www.foodauthority.nsw.gov.au/consumer/food-allergies/food-allergens/milk','https://www.foodstandards.gov.au/consumer/labelling/allergen-labelling'])
add('geography','cover','Quantify land-cover change','A 1,000 km² catchment has forest cover of 60% in Year 1 and 45% in Year 2. Calculate the area lost, the percentage-point change and the percentage decrease relative to Year 1. Propose one plausible consequence.', ['Forest area falls from 600 to 450 km²:150 km² lost. Change=−15 percentage points. Relative decrease=150/600×100=25%. Removing forest can reduce interception and increase runoff/erosion under otherwise similar conditions; the actual effect depends on replacement cover, rainfall and management.'],[('Correct lost area',1),('Correct percentage-point change',1),('Correct relative decrease',1),('Plausible qualified consequence',1)],ut=[0,1,3])
add('geography','spatial','Target a geographical response','Using the synthetic subcatchment data, identify the strongest priority for an erosion-control investigation. Justify with two variables and state one further dataset needed.', ['B is a defensible priority: it has the lowest vegetation cover (20%) and steepest mean slope (18°), both relevant to runoff/erosion risk. Rainfall intensity, soil erodibility, land management or measured sediment yield would strengthen the assessment. These three variables alone do not prove actual erosion rates.'],[('Clear priority',1),('Uses both relevant variables accurately',2),('Relevant additional dataset and purpose',1)],ut=[2,3,4],table={'headers':['Subcatchment','Vegetation cover','Mean slope'],'rows':[['A','70%','5°'],['B','20%','18°'],['C','45%','8°']]},kind='model')
add('geography','population','Calculate population change','A city starts with 200,000 people. During one year it has 3,000 births, 1,800 deaths, 5,000 arrivals and 3,200 departures. Calculate natural increase, net migration and final population.', ['Natural increase=3,000−1,800=1,200. Net migration=5,000−3,200=1,800. Total increase=3,000. Final population=203,000, assuming no other adjustments.'],[('Correct natural increase',1),('Correct net migration',1),('Correct final population',1)],et=[0,3],level='easy')
add('geography','ageing','Interpret age structure','Synthetic age shares are 0–14:15%, 15–64:60%, 65+:25%. Calculate the total age-dependency ratio using [(0–14)+(65+)]/(15–64)×100. Explain a planning implication and a limit of this ratio.', ['Ratio=(15+25)/60×100≈66.7 age dependants per 100 people aged 15–64. The relatively large older share can inform planning for accessible transport, housing or health services. Age bands do not measure actual employment or financial dependence: some older people work and some working-age people do not.'],[('Correct ratio',1),('Correct units/interpretation',1),('Relevant implication',1),('Recognises demographic proxy limitation',1)],et=[2,6])
add('digital_solutions','trace','Trace a validation algorithm','Trace this algorithm for [4, −2, 7, 0]: total←0; FOR EACH n: IF n>0 THEN total←total+n; OUTPUT total. Give the output and a boundary test for n>0.', ['The positive values are 4 and 7, so total=11. A boundary test is input 0: it should not be added. Inputs just below and above the boundary, such as −1 and 1, help test the comparison.'],[('Correct output 11',1),('Correct boundary test and expected behaviour',1)],et=[7,8],level='easy')
add('digital_solutions','sql','Select the intended records','Table Student(id, name, score) contains (1,Ana,72), (2,Ben,49), (3,Chen,85). Write SQL to return only name and score where score is at least 70, in descending score order. Give the result.', ['SELECT name, score FROM Student WHERE score >= 70 ORDER BY score DESC; Result: Chen,85 followed by Ana,72. Equivalent valid SQL earns credit.'],[('Correct columns and table',1),('Correct inclusive condition',1),('Correct descending order and result',1)],et=[9])
add('digital_solutions','hash','Hashing and encryption','A developer says “We can decrypt a password hash when a user forgets their password.” Explain the error and describe an appropriate recovery approach.', ['A cryptographic hash is designed as a one-way mapping; it is not encryption with a decryption key. Password verification compares an appropriate password-hash result, using a suitable salted password-hashing scheme. Recovery should use a securely verified reset process rather than retrieving the original password.'],[('Correct one-way versus reversible distinction',1),('Correct verification concept',1),('Appropriate reset rather than recovery of plaintext',1)],et=[0,2])
add('pe','training','Apply specificity','A player repeatedly sprints for 6 seconds with short recoveries during a match. A proposed program contains only one continuous 40-minute easy run each week. Evaluate specificity and propose one improvement.', ['The easy continuous run can contribute to aerobic fitness but does not closely reproduce repeated high-intensity sprint demands. Add appropriately planned repeated-sprint/interval work with sport-relevant movements and work–recovery periods, allowing recovery and progression. Energy systems contribute together; a 6-second sprint should not be described as using only one system.'],[('Compares program to match demands',1),('Specific suitable improvement',1),('Explains training/energy-system rationale',1)],et=[0,2,4,5],kind='model')

# Essential courses: short instructions and supplied examples.
add('essential_maths','estimate','Shopping with a budget','You have $30. You buy three items at $7.80 each and one item at $4.50. Find the total and the change.', ['Three items cost 3×$7.80=$23.40. Total=$23.40+$4.50=$27.90. Change=$30−$27.90=$2.10.'],[('Correct multiplication',1),('Correct total',1),('Correct change',1)],ut=[0],level='easy')
add('essential_maths','paint','Paint a wall','A rectangular wall is 4.0 m wide and 2.5 m high. A window covers 2.0 m². One litre of paint covers 8 m² for one coat. How many litres are needed for one coat? Ignore wastage.', ['Wall area=4×2.5=10 m². Paint area=10−2=8 m². Paint needed=8÷8=1 litre.'],[('Correct wall area',1),('Subtracts window',1),('Correct paint amount',1)],ut=[1],level='easy')
add('essential_maths','scale','Read a plan','A plan uses a scale of 1:100. A room is 45 mm long on the plan. What is the real length in metres?', ['Real length=45×100=4,500 mm. Divide by 1,000 to convert to metres:4.5 m.'],[('Correct scale multiplication',1),('Correct conversion to 4.5 m',1)],ut=[2],level='easy')
add('essential_maths','chance','Use trial results','A spinner lands on blue 18 times in 60 spins. Find the relative frequency of blue. Use this result to predict blue outcomes in another 200 spins. Is that prediction guaranteed?', ['Relative frequency=18/60=0.30 (30%). Prediction=0.30×200=60 blue outcomes. It is an estimate; random results can vary.'],[('Correct relative frequency',1),('Correct estimate',1),('Explains it is not guaranteed',1)],ut=[3],level='easy')
add('essential_english','poster','Explain a poster’s message','Read the made-up poster below. Who is it for? What does it ask them to do? Explain how ONE choice of words helps the message.', ['It is for students at the school. It asks them to bring a refillable bottle on Friday. “Small change. Less waste.” makes the action sound manageable and links it to a benefit. “Join us” gives an inclusive invitation. Either choice can be explained with a detail from the poster.'],[('Identifies the student audience',1),('Explains the action requested',1),('Uses a specific wording detail and explains its effect',2)],ut=[0,1,2],stimulus='Original practice poster — general reading skills, not a released CIA topic or paper.\nSCHOOL REFILL FRIDAY\nBring your bottle this Friday.\nSmall change. Less waste.\nJoin us at the refill station near the library.',kind='model',level='easy')
add('essential_english','compare','Two ways to present an event','Read the two made-up notices. How does each make the lunchtime reading club sound? Use a word or phrase from each to explain your answer.', ['A makes the club sound quiet and welcoming: “relax” and “read at your own pace” suggest no pressure. B makes it sound like a competition: “challenge” and “top the leaderboard” focus on winning or achievement. Both discuss reading, but they encourage students in different ways. Other supported explanations can earn credit.'],[('Explains A with a detail',2),('Explains B with a detail',2),('Makes a clear comparison',1)],ut=[0,1,2],stimulus='Original general skills practice, not a released CIA topic.\nNotice A: Need a quiet break? Relax with a book at lunchtime. Read at your own pace. Everyone is welcome.\nNotice B: Take the reading challenge! Finish five books and see if you can top the leaderboard.',kind='model',level='easy')

# Source skills are labelled hypothetical; no invented material is passed off as history.
for sid in ['ancient_history','modern_history']:
 add(sid,'source-purpose','Purpose and usefulness','Use the hypothetical source description. Explain one way the source could be useful to a historian and one limitation. Identify a further source that would help test its claim.', ['It could show how the leader wanted an audience to understand the event and what image the regime promoted. Its persuasive public purpose means it may omit defeats or exaggerate support; it cannot alone establish unanimous approval. An independently produced contemporary account, material evidence or records of opponents could corroborate or challenge the claim. Usefulness depends on the inquiry, rather than a source being simply “good” or “bad”.'],[('Usefulness linked to purpose/perspective',1),('Limitation linked to the claim',1),('Suitable corroborating source and purpose',1)],et=[2,3,4],stimulus='Hypothetical source-skills exercise, not an authentic historical quotation or evidence about your selected topic. A public statement commissioned by a ruler soon after a disputed event claims that everyone supported the ruler. It was displayed prominently for the ruler’s subjects to read.',kind='model')
 add(sid,'corroboration','Agreement is not independence','Two reports give the same account of an event, but Report B copied Report A. A third independent account disagrees. Explain why counting the two agreeing reports as two independent confirmations is weak reasoning. Suggest how to investigate the disagreement.', ['A and B share an evidential origin, so their agreement is not two independent confirmations. Examine provenance, access to the event, purpose, chronology and specific claims; compare with further independent evidence. The third source is not automatically correct merely because it is independent. Weigh evidence rather than decide by a source-count majority.'],[('Recognises dependence of A and B',1),('Explains its effect on corroboration',1),('Proposes appropriate evaluation/cross-checking',1)],et=[3,4,6],stimulus='Hypothetical source-skills exercise; apply this method to the authentic sources and topic supplied by your teacher.',kind='model')
add('atsi_studies','referendum','What changed in 1967?','Explain why it is inaccurate to say the 1967 referendum first gave Aboriginal people the right to vote in federal elections. Identify what the referendum changed.', ['Federal voting eligibility had been extended to all Aboriginal and Torres Strait Islander adults in 1962. The 1967 referendum removed the exclusion of Aboriginal people from the Commonwealth’s race power in section 51(xxvi) and repealed section 127, which excluded Aboriginal people from population reckoning for constitutional purposes. It did not itself grant the federal vote.'],[('Identifies the earlier 1962 federal change',1),('Explains the Commonwealth legislative-power change',1),('Explains repeal of section 127',1)],ut=[0,1],et=[0,2],sources=['https://aiatsis.gov.au/explore/1967-referendum','https://aiatsis.gov.au/explore/right-vote'])
add('atsi_studies','participation','Evaluate a proposed response','Using the fictional proposal, explain a concern about self-determination and recommend a specific improvement. Use the supplied evidence.', ['The proposal is being decided for the community without meaningful participation, limiting community control over priorities. Include community-selected representatives with real decision-making authority from planning through evaluation, and fund accessible consultation on community terms. The 18 expressions of interest suggest a basis for participation, but they do not prove all community members share one view.'],[('Explains decision-making/self-determination concern',1),('Uses the supplied participation evidence',1),('Specific improvement with rationale',2)],ut=[2,3],et=[7],stimulus='Fictional practice scenario, not a case study of an actual community: An agency drafts a local cultural program without speaking with the relevant Aboriginal community. Eighteen community members have asked to help shape the program. The agency plans one information meeting after all major decisions are final.',kind='model')
add('study_religion','justice-source','Teaching and social action','Use the fictional organisation statement. Explain how its stated belief supports its action, and distinguish this interpretation from a claim about every adherent of a religion.', ['The statement treats human dignity as a reason to provide practical support irrespective of background. The meal service translates that stated value into action. This evidence supports an interpretation of this organisation’s response; it does not establish what all adherents believe or do. Analysis of a real tradition requires its authentic teachings and context.'],[('Identifies value of human dignity',1),('Explains link between value and practical action',1),('Recognises limits on generalisation',1)],et=[7,8,9],stimulus='Original fictional source-skills exercise, not a sacred text or a statement from a real religion: “Our belief in the dignity of every person leads us to offer free meals to anyone who needs one, whatever their background.”',kind='model')
add('study_religion','evaluate','Evaluate an organisation’s response','Use the fictional data. Evaluate accessibility of the program and recommend an improvement. Distinguish an output from an outcome.', ['Providing 600 meals is an output: an activity delivered. Whether food insecurity decreased would be an outcome and requires further evidence. The limited opening time and travel difficulty indicate access barriers. An evening session, transport support or an additional location could improve accessibility; evaluate take-up and recipient-reported access, while considering cost and staffing.'],[('Correct output/outcome distinction',2),('Uses an accessibility barrier',1),('Justified improvement with evaluation measure',2)],et=[7,9],stimulus='Fictional data for source analysis: A religious aid organisation provides 600 meals in a month. It opens only from 12–1 pm on weekdays. Some potential recipients report being unable to travel to the venue. No information on change in household food insecurity is supplied.',kind='model')

# Original written language comprehension. No claim to supply listening audio/full papers.
langs={
'chinese':('我星期六常常和朋友一起打篮球。运动以后，我们去图书馆。我喜欢这个安排，因为既能锻炼身体，又能学习。','我明年想在大学学习工程。为了准备，我每周复习数学。我有一点担心考试，但是也很期待新的生活。'),
'french':('Le samedi, je joue souvent au basket avec mes amis. Après le sport, nous allons à la bibliothèque. Ce programme me plaît parce que je peux faire de l’exercice et étudier.','L’année prochaine, je voudrais étudier l’ingénierie à l’université. Pour me préparer, je révise les maths chaque semaine. Les examens m’inquiètent un peu, mais j’ai aussi hâte de découvrir une nouvelle vie.'),
'german':('Samstags spiele ich oft mit meinen Freunden Basketball. Nach dem Sport gehen wir in die Bibliothek. Ich mag diesen Plan, weil ich mich bewegen und lernen kann.','Nächstes Jahr möchte ich an der Universität Ingenieurwissenschaften studieren. Zur Vorbereitung wiederhole ich jede Woche Mathematik. Ich mache mir etwas Sorgen wegen der Prüfungen, freue mich aber auch auf das neue Leben.'),
'italian':('Il sabato gioco spesso a pallacanestro con i miei amici. Dopo lo sport andiamo in biblioteca. Mi piace questo programma perché posso fare movimento e studiare.','L’anno prossimo vorrei studiare ingegneria all’università. Per prepararmi ripasso matematica ogni settimana. Gli esami mi preoccupano un po’, ma non vedo l’ora di iniziare una nuova vita.'),
'japanese':('土曜日はよく友達とバスケットボールをします。スポーツの後で、図書館に行きます。運動も勉強もできるので、この予定が好きです。','来年、大学で工学を勉強したいです。準備のために、毎週数学を復習しています。試験は少し心配ですが、新しい生活も楽しみです。'),
'spanish':('Los sábados suelo jugar al baloncesto con mis amigos. Después del deporte vamos a la biblioteca. Me gusta este plan porque puedo hacer ejercicio y estudiar.','El año que viene me gustaría estudiar ingeniería en la universidad. Para prepararme, repaso matemáticas cada semana. Los exámenes me preocupan un poco, pero también tengo ganas de empezar una nueva vida.')}
for sid,(leisure,future) in langs.items():
 add(sid,'leisure-reading','Read for details and a reason','Read the original practice text. In English, identify TWO activities the speaker does on Saturdays and explain why the speaker likes the arrangement.', ['The speaker plays basketball with friends and goes to the library afterwards. The arrangement is liked because it allows both physical exercise and study. An answer should convey meaning accurately; it need not use these exact words.'],[('Basketball with friends',1),('Going to the library after sport',1),('Explains both exercise and study as the reason',2)],ut=[0,2],route=sid+'-ia1',stimulus='Original written comprehension practice (not listening audio):\n'+leisure,kind='model',level='easy')
 add(sid,'future-reading','Plans and mixed feelings','Read the original practice text. In English, identify the speaker’s study plan and preparation. Explain the speaker’s mixed feelings using two details.', ['The speaker wants to study engineering at university next year and revises mathematics every week to prepare. The speaker is a little worried about exams but also looks forward to a new life. Both concern and anticipation are needed to explain the mixed feelings.'],[('Engineering at university next year',1),('Weekly maths revision',1),('Concern about exams supported by text',1),('Positive anticipation of new life supported by text',1)],et=[2,3,5],stimulus='Original written comprehension practice (not listening audio):\n'+future,kind='model')
for sid,text,contrast in [
 ('chinese_ext','手机让我们随时与远方的朋友联系，却也可能让同桌的人不再交谈。技术并没有替我们决定怎样生活；关键在于我们怎样使用它。','“随时…联系”与“不再交谈”'),
 ('french_ext','Le téléphone nous rapproche de nos amis lointains, mais il peut aussi nous éloigner de la personne assise à côté de nous. La technologie ne choisit pas notre vie à notre place : tout dépend de l’usage que nous en faisons.','“nous rapproche” / “nous éloigner”'),
 ('german_ext','Das Handy bringt uns weit entfernten Freunden näher, kann uns aber zugleich von der Person neben uns entfernen. Die Technik entscheidet nicht für uns, wie wir leben; entscheidend ist, wie wir sie nutzen.','“näher” / “entfernen”')]:
 add(sid,'perspective-reading','Analyse a qualified viewpoint','Analyse how the original written text presents technology. In your course language, explain the viewpoint and the effect of one contrast. The model below explains the ideas in English so you can check meaning; it is not a model of target-language expression.', ['The viewpoint is qualified: technology enables contact across distance but may reduce interaction with people nearby. The contrast between bringing distant friends closer and distancing the person beside us highlights this tension. The final sentence places responsibility on how people use technology rather than treating technology as inherently good or bad. In the course language, support the analysis with a relevant phrase, such as '+contrast+'.'],[('Recognises qualified rather than wholly positive/negative viewpoint',1),('Analyses the contrast using a textual detail',2),('Explains responsibility/use in the final sentence',1)],ut=[0,1,2],route=sid+'-ia1',stimulus='Original written analysis practice; no audio component supplied:\n'+text,kind='model',level='hard')

# Build a portable, auditable release; versions count numerical variants separately.
for q in qs:
 assert q['marks']>0 and q['answer'] and q['sources']
 assert q['difficulty'] in ['easy','medium','hard']
assert len({q['id'] for q in qs})==len(qs)
bank={'version':'2026-10-14.1','attribution':'Created by Mrs Knox','notice':'Original practice questions. Marks and marking points are indicative, not official QCAA marking schemes. This starter bank samples topics; it is not a complete paper or complete syllabus coverage. Model responses show one supported approach.','questions':qs}
(ROOT/'question-bank.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n')
(ROOT/'question-data.js').write_text('window.PRACTICE_QUESTIONS = '+json.dumps(bank,ensure_ascii=False).replace('</','<\\/')+';\n')
print(f'{len(qs)} questions; {len(set((q["subject"],q["template"]) for q in qs))} templates')
for mode in ['unit3','ea']:
 print(mode, len([q for q in qs if mode in q['scopes']]), 'questions;',len(set(q['scopes'][mode]['route'] for q in qs if mode in q['scopes'])),'routes')
